// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

const { fontFamily } = loadFont();



export type ConversionProgressProps = Record<string, any>;

const ConversionProgress: React.FC<ConversionProgressProps> = ({
  backgroundColor = "#0E0E0F",
  transparentBackground = false,
  durationInSeconds = 5,
  bar1Title = "MAIN CONVERSION ACTION",
  bar1MarkerText = "400",
  bar1Subtitle = "CONVERSIONS",
  bar2Title = "ALL CONVERSION ACTIONS",
  bar2MarkerText = "20,000",
  bar2Subtitle = "ACTIONS",
  statusText1 = "BELOW THRESHOLD",
  statusText2 = "DEFAULTS TO LAST TOUCH",
  primaryColor = "#FFFFFF",
  highlightColor = "#D4571E",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timeline constants computed from ms to ensure FPS independence
  const msToFrames = useMemo(() => (ms: number) => Math.round((ms / 1000) * fps), [fps]);

  const tBar1Start = 0;
  const tBar1End = tBar1Start + msToFrames(700);

  const tMarker1FlashStart = tBar1End;
  const tMarker1FlashPeak = tMarker1FlashStart + msToFrames(100);
  const tMarker1FlashEnd = tMarker1FlashStart + msToFrames(200);

  const tBar2Start = tMarker1FlashEnd + msToFrames(200);
  const tBar2End = tBar2Start + msToFrames(700);

  const tMarker2FlashStart = tBar2End;
  const tMarker2FlashPeak = tMarker2FlashStart + msToFrames(100);
  const tMarker2FlashEnd = tMarker2FlashStart + msToFrames(200);

  const tStatusFadeInStart = tMarker2FlashEnd + msToFrames(150);
  const tStatusFadeInEnd = tStatusFadeInStart + msToFrames(300);

  // Increased by 1000ms (1 second) to let "Below the threshold" stay longer before cross-fading
  const tCrossFadeStart = tStatusFadeInEnd + msToFrames(1400);
  const tCrossFadeEnd = tCrossFadeStart + msToFrames(200);

  // Animations - Stop below the 60% threshold (e.g., at 52%)
  const bar1Progress = interpolate(frame, [tBar1Start, tBar1End], [0, 52], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const bar2Progress = interpolate(frame, [tBar2Start, tBar2End], [0, 52], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const getFlashColor = (tStart: number, tPeak: number, tEnd: number) => {
    if (frame <= tStart) return primaryColor;
    if (frame >= tEnd) return primaryColor;
    return interpolateColors(
      frame,
      [tStart, tPeak, tEnd],
      [primaryColor, highlightColor, primaryColor]
    );
  };

  const m1Color = getFlashColor(tMarker1FlashStart, tMarker1FlashPeak, tMarker1FlashEnd);
  const m2Color = getFlashColor(tMarker2FlashStart, tMarker2FlashPeak, tMarker2FlashEnd);

  const status1Opacity = interpolate(frame, [tStatusFadeInStart, tStatusFadeInEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const status1CrossFadeOut = interpolate(frame, [tCrossFadeStart, tCrossFadeEnd], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const status2Opacity = interpolate(frame, [tCrossFadeStart, tCrossFadeEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const finalStatus1Opacity = Math.min(status1Opacity, status1CrossFadeOut);

  // Dimensions
  const barWidth = width * (1400 / 1920);
  const barHeight = height * (64 / 1080);
  const borderThickness = 2 * s;
  const markerExtension = 16 * s;

  const titleSize = 20 * s;
  const subtitleSize = 18 * s;
  const statusSize = 32 * s;

  const renderBar = (
    y: number,
    title: string,
    markerText: string,
    subtitle: string,
    progress: number,
    markerColor: string
  ) => {
    return (
      <div
        style={{
          position: "absolute",
          top: y,
          left: "50%",
          transform: "translateX(-50%)",
          width: barWidth,
          height: barHeight,
          border: `${borderThickness}px solid ${primaryColor}`,
          boxSizing: "border-box",
          backgroundColor: transparentBackground ? "transparent" : backgroundColor,
        }}
      >
        {/* Progress Fill */}
        <div
          style={{
            height: "100%",
            width: `${progress}%`,
            backgroundColor: primaryColor,
          }}
        />

        {/* 60% Marker Line */}
        <div
          style={{
            position: "absolute",
            left: `60%`,
            top: -(markerExtension + borderThickness),
            bottom: -(markerExtension + borderThickness),
            width: borderThickness,
            backgroundColor: markerColor,
            transform: "translateX(-50%)",
            zIndex: 10,
          }}
        />

        {/* Title */}
        <div
          style={{
            position: "absolute",
            bottom: "100%",
            left: 0,
            marginBottom: 20 * s,
            color: primaryColor,
            fontSize: titleSize,
            fontWeight: 900,
            textTransform: "uppercase",
            whiteSpace: "nowrap",
          }}
        >
          {title}
        </div>

        {/* Marker Number */}
        <div
          style={{
            position: "absolute",
            bottom: "100%",
            left: "60%",
            transform: "translateX(-50%)",
            marginBottom: 20 * s,
            color: highlightColor,
            fontSize: titleSize,
            fontWeight: 900,
            whiteSpace: "nowrap",
          }}
        >
          {markerText}
        </div>

        {/* Subtitle */}
        <div
          style={{
            position: "absolute",
            top: "100%",
            right: 0,
            marginTop: 16 * s,
            color: primaryColor,
            fontSize: subtitleSize,
            fontWeight: 900,
            textTransform: "uppercase",
            whiteSpace: "nowrap",
          }}
        >
          {subtitle}
        </div>
      </div>
    );
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, transition: "none" }}>
      {renderBar(
        height * (440 / 1080),
        bar1Title,
        bar1MarkerText,
        bar1Subtitle,
        bar1Progress,
        m1Color
      )}
      {renderBar(
        height * (640 / 1080),
        bar2Title,
        bar2MarkerText,
        bar2Subtitle,
        bar2Progress,
        m2Color
      )}

      {/* Status Texts Container */}
      <div
        style={{
          position: "absolute",
          top: height * (840 / 1080),
          width: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* Status 1 */}
        <div
          style={{
            position: "absolute",
            color: primaryColor,
            fontSize: statusSize,
            fontWeight: 900,
            textTransform: "uppercase",
            opacity: finalStatus1Opacity,
            whiteSpace: "nowrap",
            transition: "none",
          }}
        >
          {statusText1}
        </div>

        {/* Status 2 */}
        <div
          style={{
            position: "absolute",
            color: primaryColor,
            fontSize: statusSize,
            fontWeight: 900,
            textTransform: "uppercase",
            opacity: status2Opacity,
            whiteSpace: "nowrap",
            transition: "none",
          }}
        >
          {statusText2}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ConversionProgress;